"""Public facade that composes pdf-craft's independent components."""

from collections.abc import Callable, Container, Sequence
from contextlib import contextmanager
from dataclasses import dataclass
from inspect import signature
from os import PathLike
from pathlib import Path
from tempfile import TemporaryDirectory
from typing import Iterator, Literal, cast

from epub_generator import BookMeta, LaTeXRender, TableRender

from .document import DocumentPackage
from .extractor.chapter.chapter import Chapter, ParagraphLayout
from .extractor.chapter.reader import create_chapters_reader
from .error import IgnoreOCRErrorsChecker, IgnorePDFErrorsChecker
from .extractor import PDFExtractor
from .llm import LLM
from .metering import AbortedCheck, OCRTokensMetering
from .ocr_config import OCRConfig
from .pdf import DeepSeekOCRSize, OCREvent, PDFHandler
from .pipeline.epub import translate_epub as run_epub_translation
from .pipeline.pdf import PDFTranslationPipeline
from .pipeline.pdf.pipeline import _to_patch_text
from .renderer import EpubRenderer, MarkdownRenderer
from .transformer import ChapterPackageTransformer, ChapterTransformer, PackageTransformer, SubmitKind


@dataclass(frozen=True)
class TranslationStep:
    """A user-requested content transformation inserted before rendering."""

    transformer: ChapterTransformer | PackageTransformer
    mode: SubmitKind = SubmitKind.REPLACE


@dataclass(frozen=True)
class PDFOptions:
    """Long-lived infrastructure needed only when extracting a PDF."""

    ocr: OCRConfig | None = None
    pdf_handler: PDFHandler | None = None
    models_cache_path: PathLike | str | None = None
    local_only: bool = False


@dataclass(frozen=True)
class ExtractionOptions:
    """Controls for one PDF extraction run."""

    page_indexes: Container[int] | None = None
    ocr_size: DeepSeekOCRSize = "gundam"
    dpi: int | None = None
    max_page_image_file_size: int | None = None
    max_ocr_tokens: int | None = None
    max_ocr_output_tokens: int | None = None
    includes_cover: bool = False
    includes_footnotes: bool = False
    generate_plot: bool = False
    toc_assumed: bool = False
    toc_llm: LLM | None = None
    ignore_pdf_errors: IgnorePDFErrorsChecker = False
    ignore_ocr_errors: IgnoreOCRErrorsChecker = False
    aborted: AbortedCheck = lambda: False
    on_ocr_event: Callable[[OCREvent], None] = lambda _: None


class PDFCraft:
    """Compose extraction, rendering, and format-specific translation workflows.

    Constructing this facade does not initialise OCR.  EPUB-only callers can
    therefore use ``PDFCraft()`` without PDF infrastructure or credentials.
    """

    def __init__(self, pdf: PDFOptions | None = None, *, _engine=None) -> None:
        self._pdf = pdf
        self._engine = _engine

    @classmethod
    def from_engine(cls, engine) -> "PDFCraft":
        return cls(_engine=engine)

    def extract_pdf(
        self, source: PathLike | str, package_path: PathLike | str,
        options: ExtractionOptions | None = None,
    ) -> DocumentPackage:
        package, _ = self.extract_pdf_with_metering(source, package_path, options)
        return package

    def extract_pdf_with_metering(
        self, source: PathLike | str, package_path: PathLike | str,
        options: ExtractionOptions | None = None,
    ) -> tuple[DocumentPackage, OCRTokensMetering]:
        options = options or ExtractionOptions()
        return PDFExtractor(self._pdf_engine()).extract_with_metering(
            Path(source), Path(package_path),
            page_indexes=options.page_indexes,
            ocr_size=options.ocr_size, dpi=options.dpi,
            max_page_image_file_size=options.max_page_image_file_size,
            max_tokens=options.max_ocr_tokens,
            max_output_tokens=options.max_ocr_output_tokens,
            includes_cover=options.includes_cover,
            includes_footnotes=options.includes_footnotes,
            generate_plot=options.generate_plot,
            toc_assumed=options.toc_assumed, toc_llm=options.toc_llm,
            ignore_pdf_errors=options.ignore_pdf_errors,
            ignore_ocr_errors=options.ignore_ocr_errors,
            aborted=options.aborted, on_ocr_event=options.on_ocr_event,
        )

    def render_markdown(
        self, package: DocumentPackage, output: PathLike | str,
        assets_path: PathLike | str | None = None,
        *, aborted: AbortedCheck = lambda: False,
    ) -> None:
        MarkdownRenderer().render(package, Path(output),
                                  Path(assets_path) if assets_path is not None else None,
                                  aborted=aborted)

    def translate_package(
        self, package: DocumentPackage, output_path: PathLike | str,
        translator: ChapterTransformer,
        *, submit: SubmitKind = SubmitKind.REPLACE,
    ) -> DocumentPackage:
        """Translate one render-ready package into another package.

        The public operation is intentionally singular and translation-focused;
        arbitrary package transformation chains remain an internal composition
        detail used by the compatibility workflows.
        """
        package_transformer = ChapterPackageTransformer(translator, mode=submit)
        return package_transformer.transform(package, Path(output_path))

    def render_epub(
        self, package: DocumentPackage, output: PathLike | str, *,
        book_meta: BookMeta | None = None, lan: Literal["zh", "en"] = "zh",
        table_render: TableRender = TableRender.HTML,
        latex_render: LaTeXRender = LaTeXRender.MATHML,
        inline_latex: bool = True,
        aborted: AbortedCheck = lambda: False,
    ) -> None:
        EpubRenderer().render(package, Path(output), book_meta=book_meta, lan=lan,
                              table_render=table_render, latex_render=latex_render,
                              inline_latex=inline_latex, aborted=aborted)

    def translate_pdf(
        self, source: PathLike | str, package: DocumentPackage,
        output: PathLike | str, transformer: ChapterTransformer | Callable[[str], str],
        *, steps: Sequence[TranslationStep | PackageTransformer] = (),
    ) -> None:
        for step in steps:
            mode = _step_mode(step, self._as_package_transformer(step))
            if mode == SubmitKind.APPEND_BLOCK:
                raise ValueError("PDF output does not support APPEND_BLOCK")
        with TemporaryDirectory(prefix="pdf-craft-translated-package-") as directory:
            translated = self._translate_for_pdf(package, Path(directory), transformer, steps)
            self.patch_pdf_with_package(source, translated, output)

    def patch_pdf_with_package(
        self,
        source: PathLike | str,
        package: DocumentPackage | PathLike | str,
        output: PathLike | str,
    ) -> None:
        """Patch an existing PDF with text and geometry from a DocumentPackage."""
        package = package if isinstance(package, DocumentPackage) else DocumentPackage.from_path(Path(package))
        package.validate()
        _validate_package_for_pdf(Path(source), package)
        PDFTranslationPipeline(
            pdf_handler=self._pdf.pdf_handler if self._pdf else None
        ).patch(Path(source), Path(output), package)

    def translate_epub(self, source: PathLike | str, output: PathLike | str, *,
                       target_language: str, submit: SubmitKind,
                       **options) -> None:
        run_epub_translation(source, output, target_language, submit, **options)

    def convert_pdf_to_markdown(
        self, source: PathLike | str, output: PathLike | str, *,
        package_path: PathLike | str | None = None, extraction: ExtractionOptions | None = None,
        assets_path: PathLike | str | None = None,
        steps: Sequence[TranslationStep | PackageTransformer] = (),
    ) -> OCRTokensMetering:
        with _package_workspace(package_path) as workspace:
            package, metering = self.extract_pdf_with_metering(source, workspace, extraction)
            package = self._apply_steps(package, steps)
            self.render_markdown(package, output, assets_path,
                                 aborted=(extraction or ExtractionOptions()).aborted)
            return metering

    def convert_pdf_to_epub(
        self, source: PathLike | str, output: PathLike | str, *,
        package_path: PathLike | str | None = None, extraction: ExtractionOptions | None = None,
        book_meta: BookMeta | None = None, lan: Literal["zh", "en"] = "zh",
        table_render: TableRender = TableRender.HTML,
        latex_render: LaTeXRender = LaTeXRender.MATHML,
        inline_latex: bool = True,
        steps: Sequence[TranslationStep | PackageTransformer] = (),
    ) -> OCRTokensMetering:
        extraction = extraction or ExtractionOptions()
        with _package_workspace(package_path) as workspace:
            package, metering = self.extract_pdf_with_metering(source, workspace, extraction)
            package = self._apply_steps(package, steps)
            if book_meta is None:
                book_meta = self._extract_book_meta(Path(source))
            self.render_epub(package, output, book_meta=book_meta, lan=lan,
                             table_render=table_render, latex_render=latex_render,
                             inline_latex=inline_latex, aborted=extraction.aborted)
            return metering

    def _apply_steps(
        self, package: DocumentPackage,
        steps: Sequence[TranslationStep | PackageTransformer],
    ) -> DocumentPackage:
        current = package
        for index, step in enumerate(steps):
            transformer = self._as_package_transformer(step)
            output = package.chapters_path.parent / f"transformed-{index}"
            current = transformer.transform(current, output)
        return current

    def _translate_for_pdf(
        self,
        package: DocumentPackage,
        output_root: Path,
        transformer: ChapterTransformer | Callable[[str], str],
        steps: Sequence[TranslationStep | PackageTransformer],
    ) -> DocumentPackage:
        current = package
        if callable(transformer):
            transformer = _TextChapterTransformer(transformer)
        current = self.translate_package(current, output_root / "translated", transformer)
        if steps:
            current = self._apply_steps(current, steps)
        return current

    @staticmethod
    def _as_package_transformer(step: TranslationStep | PackageTransformer) -> PackageTransformer:
        if not isinstance(step, TranslationStep):
            return step
        transformer = step.transformer
        if isinstance(transformer, ChapterPackageTransformer):
            if step.mode != SubmitKind.REPLACE and transformer.mode != step.mode:
                return ChapterPackageTransformer(
                    transformer.chapter_transformer, mode=step.mode
                )
            return transformer
        if _accepts_package(transformer):
            return cast(PackageTransformer, transformer)
        return ChapterPackageTransformer(cast(ChapterTransformer, transformer), mode=step.mode)

    def _pdf_engine(self):
        if self._engine is not None:
            return self._engine
        if self._pdf is None:
            raise ValueError("PDF extraction requires PDFCraft(pdf=PDFOptions(...))")
        # Import lazily so EPUB-only callers never import the historical adapter.
        from .transform import PDFExtractionEngine
        return PDFExtractionEngine(models_cache_path=self._pdf.models_cache_path,
                         pdf_handler=self._pdf.pdf_handler,
                         local_only=self._pdf.local_only, ocr=self._pdf.ocr)

    def _extract_book_meta(self, source: Path) -> BookMeta | None:
        engine = self._pdf_engine()
        extract = getattr(engine, "_extract_book_meta", None)
        return extract(source) if extract is not None else None


@contextmanager
def _package_workspace(package_path: PathLike | str | None) -> Iterator[Path]:
    """Provide a persistent package path or a cleaned-up temporary workspace."""
    if package_path is not None:
        yield Path(package_path)
        return
    with TemporaryDirectory(prefix="pdf-craft-package-") as directory:
        yield Path(directory)


def _accepts_package(transformer: ChapterTransformer | PackageTransformer) -> bool:
    """Recognise the public PackageTransformer method shape explicitly."""
    try:
        parameters = list(signature(transformer.transform).parameters.values())
    except (TypeError, ValueError):
        return False
    positional = [
        parameter for parameter in parameters
        if parameter.kind in (parameter.POSITIONAL_ONLY, parameter.POSITIONAL_OR_KEYWORD)
    ]
    return len(positional) == 2 and [parameter.name for parameter in positional] == [
        "package", "output_path"
    ]


def _step_mode(step: TranslationStep | PackageTransformer, transformer: PackageTransformer) -> SubmitKind | None:
    if isinstance(step, TranslationStep):
        return step.mode if step.mode != SubmitKind.REPLACE else getattr(transformer, "mode", step.mode)
    return getattr(transformer, "mode", None)


class _TextChapterTransformer:
    """Adapt the legacy block-text callback to the package transformer shape."""

    def __init__(self, callback: Callable[[str], str]) -> None:
        self._callback = callback

    def transform(self, chapter: Chapter) -> Chapter:
        for layout in chapter.layouts:
            if not isinstance(layout, ParagraphLayout):
                continue
            for block in layout.blocks:
                text = _to_patch_text(block.content)
                translated = self._callback(text)
                if translated != text:
                    block.content = [translated]
        return chapter


def _validate_package_for_pdf(source: Path, package: DocumentPackage) -> None:
    """Fail before patching when package geometry cannot match the PDF."""
    try:
        import pypdf
    except ImportError as error:
        raise RuntimeError("PDF patching requires the optional 'pypdf' dependency") from error
    page_sizes = package.page_pixel_sizes()
    if not page_sizes:
        raise ValueError("DocumentPackage is missing page geometry metadata required for PDF patching")
    page_count = len(pypdf.PdfReader(str(source)).pages)
    chapter_pages = {
        block.page_index
        for chapter in create_chapters_reader(package.chapters_path)()
        for layout in chapter.layouts
        if isinstance(layout, ParagraphLayout)
        for block in layout.blocks
    }
    invalid = sorted(page for page in set(page_sizes) | chapter_pages if page > page_count)
    if invalid:
        raise ValueError(
            "DocumentPackage page geometry exceeds source PDF page count: "
            f"pages {invalid} of {page_count}"
        )
    missing = sorted(page for page in chapter_pages if page not in page_sizes)
    if missing:
        raise ValueError(
            "DocumentPackage is missing page geometry for chapter pages: "
            f"{missing}"
        )

from dataclasses import dataclass
from enum import Enum, auto
from typing import Callable

AbortedCheck = Callable[[], bool]


def check_aborted(aborted_check: AbortedCheck) -> None:
    if aborted_check():
        from doc_page_extractor.extraction_context import AbortError

        raise AbortError()


@dataclass
class OCRTokensMetering:
    input_tokens: int
    output_tokens: int


class InterruptedKind(Enum):
    ABORT = auto()
    TOKEN_LIMIT_EXCEEDED = auto()

from typing import Callable

from .metering import InterruptedKind, OCRTokensMetering


class PDFError(Exception):
    def __init__(self, message: str, page_index: int | None = None) -> None:
        super().__init__(message)
        self.page_index: int | None = page_index


class OCRError(Exception):
    def __init__(self, message: str, page_index: int, step_index: int) -> None:
        super().__init__(message)
        self.page_index: int = page_index
        self.step_index: int = step_index


class NoUsableOCRPagesError(Exception):
    """Raised when every requested OCR page failed after errors were ignored."""

    def __init__(self, failed_page_indexes: tuple[int, ...]) -> None:
        self.failed_page_indexes = failed_page_indexes
        pages = ", ".join(str(index) for index in failed_page_indexes)
        super().__init__(
            "OCR produced no usable pages; all requested pages failed after "
            f"errors were ignored: {pages}"
        )


def is_inline_error(error: Exception) -> bool:
    return isinstance(error, (PDFError, OCRError))


IgnorePDFErrorsChecker = bool | Callable[[PDFError], bool]
IgnoreOCRErrorsChecker = bool | Callable[[OCRError], bool]


# 不可直接用 doc-page-extractor 的 Error，该库的一切都是懒加载，若暴露，则无法懒加载
class InterruptedError(Exception):
    """Raised when the operation is interrupted by the user."""

    def __init__(self, kind: InterruptedKind, metering: OCRTokensMetering) -> None:
        super().__init__()
        self._kind: InterruptedKind = kind
        self._metering: OCRTokensMetering = metering

    @property
    def kind(self) -> InterruptedKind:
        return self._kind

    @property
    def metering(self) -> OCRTokensMetering:
        return self._metering


def to_interrupted_error(error: Exception) -> InterruptedError | None:
    from doc_page_extractor.extraction_context import (
        AbortError,
        ExtractionAbortedError,
        TokenLimitError,
    )

    if isinstance(error, ExtractionAbortedError):
        kind: InterruptedKind | None = None
        if isinstance(error, AbortError):
            kind = InterruptedKind.ABORT
        elif isinstance(error, TokenLimitError):
            kind = InterruptedKind.TOKEN_LIMIT_EXCEEDED

        if kind is not None:
            return InterruptedError(
                kind=kind,
                metering=OCRTokensMetering(
                    input_tokens=error.input_tokens,
                    output_tokens=error.output_tokens,
                ),
            )
    return None

import logging
import re
from pathlib import Path

from ...common import XMLReader, read_xml, save_xml
from ...llm import LLM
from ...pdf import TITLE_TAGS, Page
from ...pdf import decode as decode_pdf
from .llm_analyser import (
    LLMAnalysisError,
    analyse_title_levels_by_llm,
    analyse_toc_levels_by_llm,
)
from .toc_levels import Ref2Level, analyse_title_levels, analyse_toc_levels
from .toc_pages import PageRef, find_toc_pages
from .types import Toc, TocInfo
from .types import decode as decode_toc
from .types import encode as encode_toc

logger = logging.getLogger(__name__)

_TITLE_HEAD_REGX = re.compile(r"^\s*#{1,6}\s*")


def analyse_toc(
    pages_path: Path,
    toc_path: Path,
    toc_assumed: bool,
    toc_llm: LLM | None = None,
) -> TocInfo:
    if toc_path.exists():
        return decode_toc(read_xml(toc_path))

    toc_path.parent.mkdir(parents=True, exist_ok=True)
    toc_info = _do_analyse_toc(pages_path, toc_llm, toc_assumed)
    save_xml(encode_toc(toc_info), toc_path)

    return toc_info


def _do_analyse_toc(
    pages_path: Path,
    toc_llm: LLM | None,
    toc_assumed: bool,
) -> TocInfo:
    pages: XMLReader[Page] = XMLReader(
        prefix="page",
        dir_path=pages_path,
        decode=decode_pdf,
    )
    toc_pages: list[PageRef] = []
    if toc_assumed:
        toc_pages = find_toc_pages(
            iter_titles=lambda: (
                list(
                    (layout.order, _TITLE_HEAD_REGX.sub("", layout.text))
                    for layout in page.body_layouts
                    if layout.ref in TITLE_TAGS
                )
                for page in pages.read()
            ),
            iter_page_bodies=lambda: (
                "".join(layout.text for layout in page.body_layouts)
                for page in pages.read()
            ),
        )

    ref2level: Ref2Level | None = None
    toc_page_indexes: list[int] = []

    if toc_pages:
        if toc_llm is not None:
            try:
                ref2level = analyse_toc_levels_by_llm(
                    llm=toc_llm,
                    toc_page_refs=toc_pages,
                    toc_page_contents=list(
                        pages.read(
                            page_indexes={
                                toc_page.page_index for toc_page in toc_pages
                            },
                        )
                    ),
                )
            except LLMAnalysisError as error:
                print(
                    f"LLM analysis toc failed, falling back to statistical method: {error}"
                )

        if ref2level is None:
            ref2level = analyse_toc_levels(
                pages=pages,
                pages_path=pages_path,
                toc_pages=toc_pages,
            )
        toc_page_indexes.extend(ref.page_index for ref in toc_pages)
        toc_page_indexes.sort()

    else:
        if toc_llm is not None:
            try:
                ref2level = analyse_title_levels_by_llm(toc_llm, pages)
            except LLMAnalysisError as error:
                print(
                    f"LLM analysis title failed, falling back to statistical method: {error}"
                )

        if ref2level is None:
            ref2level = analyse_title_levels(pages)

    return TocInfo(
        content=_structure_toc_by_levels(ref2level),
        page_indexes=toc_page_indexes,
    )


def _structure_toc_by_levels(ref2level: Ref2Level) -> list[Toc]:
    # virtual root
    root = Toc(
        id=-1,
        page_index=-1,
        order=-1,
        level=-1,
        children=[],
    )
    next_id: int = 1
    stack: list[Toc] = [root]

    for (page_index, order), level in sorted(ref2level.items(), key=lambda x: x[0]):
        toc = Toc(
            id=next_id,
            page_index=page_index,
            order=order,
            level=level,
            children=[],
        )
        next_id += 1
        while stack and stack[-1].level >= level:
            stack.pop()

        if not stack:
            break

        stack[-1].children.append(toc)
        stack.append(toc)

    return root.children

from os import PathLike
from pathlib import Path
from typing import Generator

from PIL.Image import Image

from ..error import PDFError
from .handler import DefaultPDFHandler, PDFDocument, PDFHandler


def pdf_pages_count(
    pdf_path: PathLike | str,
    pdf_handler: PDFHandler | None = None,
) -> int:
    if pdf_handler is None:
        pdf_handler = DefaultPDFHandler()
    document: PDFDocument | None = None
    try:
        document = pdf_handler.open(pdf_path=Path(pdf_path))
        return document.pages_count
    except PDFError:
        raise
    except Exception as error:
        raise PDFError("Failed to parse PDF document.", page_index=None) from error
    finally:
        if document is not None:
            document.close()


class PageRefContext:
    def __init__(
        self,
        pdf_path: Path,
        pdf_handler: PDFHandler,
    ) -> None:
        self._pdf_path = pdf_path
        self._pdf_handler: PDFHandler = pdf_handler
        self._document: PDFDocument | None = None

    @property
    def pages_count(self) -> int:
        assert self._document is not None
        return self._document.pages_count

    def __enter__(self) -> "PageRefContext":
        assert self._document is None
        try:
            self._document = self._pdf_handler.open(self._pdf_path)
        except PDFError:
            raise
        except Exception as error:
            raise PDFError("Failed to open PDF document.", page_index=None) from error
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> None:
        if self._document is not None:
            self._document.close()
            self._document = None

    def __iter__(self) -> Generator["PageRef", None, None]:
        assert self._document is not None
        for i in range(self._document.pages_count):
            yield PageRef(
                document=self._document,
                page_index=i + 1,
            )


_PNG_COMPRESSION_RATIO = 0.5  # Conservative estimate for document images
_BYTES_PER_PIXEL = 3  # RGB


class PageRef:
    def __init__(
        self,
        document: PDFDocument,
        page_index: int,
    ) -> None:
        self._document = document
        self._page_index = page_index

    @property
    def page_index(self) -> int:
        return self._page_index

    def render(self, dpi: int, max_image_file_size: int | None = None) -> Image:
        try:
            if max_image_file_size is not None:
                width_inch, height_inch = self._document.page_size(self._page_index)
                max_dpi = round(
                    self._dpi_with_size(
                        file_size=max_image_file_size,
                        width_inch=width_inch,
                        height_inch=height_inch,
                    )
                )
                dpi = min(dpi, max_dpi)

            return self._document.render_page(
                page_index=self._page_index,
                dpi=dpi,
            )
        except PDFError as error:
            error.page_index = self._page_index
            raise error

        except Exception as error:
            raise PDFError(
                f"Failed to render page {self._page_index}.",
                page_index=self._page_index,
            ) from error

    def _dpi_with_size(
        self, file_size: int, width_inch: float, height_inch: float
    ) -> float:
        # Formula: file_size = width_px * height_px * bytes_per_pixel * compression_ratio
        # where width_px = width_inch * dpi, height_px = height_inch * dpi
        return (
            file_size
            / (width_inch * height_inch * _BYTES_PER_PIXEL * _PNG_COMPRESSION_RATIO)
        ) ** 0.5

    return any(
        key in translation
        for key in ("llm_profile", "translation_llm_profile", "fill_llm_profile")
    )


def _resolve_matrix_runtime(run: SmokeRun, output_root: Path) -> SmokeRun:
    _validate_ocr_size(run.backend, run.ocr_size)
    ocr = run.ocr
    if run.backend and ocr is None:
        ocr = ocr_values_from_env(run.backend)
    translation = _resolve_translation_profiles(run.translation, output_root)
    return replace(run, ocr=ocr, translation=translation)


def _resolve_translation_profiles(translation: dict[str, Any] | None, output_root: Path) -> dict[str, Any] | None:
    if not translation:
        return translation
    resolved = dict(translation)
    profile = resolved.pop("llm_profile", None)
    translation_profile = resolved.pop("translation_llm_profile", profile)
    fill_profile = resolved.pop("fill_llm_profile", profile)
    if translation_profile and "llm" not in resolved:
        resolved["llm"] = llm_values_from_env(
            str(translation_profile),
            cache_path=output_root / "_c" / "t",
            log_dir_path=output_root / "_l" / "t",
        )
    if fill_profile and fill_profile != translation_profile and "fill_llm" not in resolved:
        resolved["fill_llm"] = llm_values_from_env(
            str(fill_profile),
            cache_path=output_root / "_c" / "f",
            log_dir_path=output_root / "_l" / "f",
        )
    return resolved


def _extract(args: argparse.Namespace, package_path: Path) -> _ExtractionResult:
    load_project_env(_project_root())
    ocr_mode = cast(OCRMode | None, args.ocr_mode) or ocr_mode_from_env()
    ocr_size = _resolve_ocr_size(args.ocr_size, ocr_mode, args.default_ocr_size)
    _validate_ocr_size(ocr_mode, ocr_size)
    _record_pdf_cache_owner(package_path.parent, args, ocr_mode, ocr_size)
    craft = PDFCraft(pdf=PDFOptions(ocr=create_ocr_config_from_env(ocr_mode)))
    package, metering = craft.extract_pdf_with_metering(
        args.source, package_path, ExtractionOptions(
            page_indexes=_page_indexes(args.pages), ocr_size=cast(Any, ocr_size), dpi=args.dpi,
            max_page_image_file_size=args.max_page_image_file_size,
            max_ocr_tokens=args.max_ocr_tokens, max_ocr_output_tokens=args.max_ocr_output_tokens,
            includes_cover=args.cover, includes_footnotes=args.footnotes,
            generate_plot=args.plot, toc_assumed=args.toc_assumed,
            toc_llm=(create_llm_from_env(args.toc_llm, cache_path=package_path.parent / "toc-cache",
                log_dir_path=package_path.parent / "toc-logs") if args.toc_llm else None),
            on_ocr_event=_print_ocr_event,
        )
    )
    return _ExtractionResult(craft, package, metering)


def _xml_transformer(args: argparse.Namespace, work_dir: Path) -> ChapterXMLTransformer:
    translation_llm = create_llm_from_env(args.translation_llm,
        cache_path=work_dir / "translation-cache", log_dir_path=work_dir / "translation-logs")
    fill_llm = translation_llm if args.fill_llm == args.translation_llm else create_llm_from_env(args.fill_llm,
        cache_path=work_dir / "fill-cache", log_dir_path=work_dir / "fill-logs")
    translator = XMLTranslator(
        translation_llm=translation_llm, fill_llm=fill_llm, target_language=args.target_language,
        user_prompt=args.prompt, ignore_translated_error=False, max_retries=args.max_retries,
        max_fill_displaying_errors=3, max_group_score=args.max_group_tokens,
        cache_seed_content=f"pdf-craft-tool:{args.target_language}",
    )
    return ChapterXMLTransformer(cast(Any, translator))


def _render(craft: PDFCraft, package: DocumentPackage, format_name: str, output: Path) -> None:
    if format_name == "markdown":
        craft.render_markdown(package, output, Path("assets"))
    else:
        craft.render_epub(package, output)


def _work_dir(source: Path, requested: Path | None, operation: str) -> Path:
    if requested is not None:
        path = requested
        if path.exists() and not path.is_dir():
            raise SystemExit(f"Work directory is not a directory: {path}")
        path.mkdir(parents=True, exist_ok=True)
        return path
    return create_run_directory(DEFAULT_OUTPUT_ROOT / "manual", f"{source.stem}-{operation}")

